    }

    double getArea() const { return totalArea; }
    double getPricePerSqm() const { return pricePerSqm; }

    void print() const {
        cout << "Площадь: " << totalArea << " кв.м, "
             << "Цена за 1 кв.м: " << pricePerSqm << " у.е., "
             << "Общая стоимость: " << getTotalPrice() << " у.е." << endl;
    }
};

int main() {
    setlocale(LC_ALL, "Russian");

    vector<Apartment> apartments = {
        Apartment(45.5, 1200.0),
        Apartment(60.0, 1100.0),
        Apartment(85.2, 1150.0),
        Apartment(33.0, 1300.0),
        Apartment(100.0, 1400.0)
    };

    cout << "Все квартиры:" << endl;
    for (const auto& apt : apartments) {
        apt.print();
    }
    cout << endl;

    double maxPrice;
    cout << "Введите максимальную сумму (стоимость квартиры): ";
    cin >> maxPrice;

    cout << "\nКвартиры стоимостью не более " << maxPrice << " у.е.:" << endl;
    bool found = false;
    for (const auto& apt : apartments) {
        if (apt.getTotalPrice() <= maxPrice) {
            apt.print();
            found = true;
        }
    }

    if (!found) {
        cout << "Квартир, удовлетворяющих данному условию, не найдено." << endl;
    }

    return 0;
}

```

---

## 1. Класс `Apartment`

```cpp
class Apartment {
private:
    ...
```
- Ключевое слово **`class`** объявляет новый тип данных.
- Блок **`private:`** означает, что поля закрыты от прямого доступа извне (из функции `main`). Это принцип **инкапсуляции**. Мы не можем в `main` написать: `obj.field = 5;`.

```cpp
public:
    Apartment(...) {
        ...
    }
```
- Блок **`public:`** содержит методы, доступные всем.
- Метод `Apartment(...)` без типа возвращаемого значения и с именем, совпадающим с именем класса, называется **конструктором**. Он вызывается автоматически при создании объекта. Его задача — проинициализировать приватные переменные переданными значениями.

### Методы класса
- **Геттеры** (`get...()`): так как поля `private`, для чтения их значений снаружи пишутся специальные функции-читатели.
- **`print()`**: выводит все параметры объекта в консоль.
- Ключевое слово **`const`** в конце метода означает, что он **не изменяет** внутреннее состояние (поля) объекта, а только читает их.

## 2. Главная функция `main`

```cpp
    setlocale(LC_ALL, "Russian");
```
- Устанавливает кодовую страницу для консоли Windows, чтобы кириллица выводилась без "кракозябр".

```cpp
    vector<Apartment> items = { ... };
```
- Создаётся контейнер `vector` с объектами класса `Apartment`. В C++ вместо обычных массивов принято использовать `vector`, так как он автоматически управляет памятью и может менять свой размер.

```cpp
    for (const auto& item : items) {
        item.print();
    }
```
- Это *Range-based for loop* (цикл по диапазону). Он автоматически проходит по всем элементам вектора.
- `const auto& item` означает, что мы берём каждый объект по **константной ссылке**. Это предотвращает лишнее копирование данных в памяти и защищает объект от случайных изменений.

### Логика задания
Напечатать параметры квартир и все квартиры, стоимость которых не превышает заданной суммы (вводится с клавиатуры).
Для выполнения индивидуального задания мы проходим по контейнеру и используем публичные методы класса для проверки условий и вычисления результатов.

